const canvas=document.getElementById('c'),ctx=canvas.getContext('2d'),game=document.getElementById('game');
const loading=document.getElementById('loading'),savesEl=document.getElementById('saves');
const saveKey='abdias_builds_saves_v1';
let saves=[];try{saves=JSON.parse(localStorage.getItem(saveKey)||'null')||[]}catch(e){saves=[]}
for(let i=0;i<3;i++){if(!saves[i])saves[i]={level:0,parts:0,name:'Novo jogo'}}
function renderSaves(){savesEl.innerHTML='';saves.forEach((s,i)=>{const b=document.createElement('button');b.className='save';b.innerHTML='<b>SAVE '+(i+1)+' — '+(s.name||'Novo jogo')+'</b><span>'+((s.level||0)===0?'Sem progresso':levels[s.level]?.name||'Aventura concluída')+'<br>'+('Peças: '+(s.parts||0))+'</span>';b.onclick=()=>startSave(i);savesEl.appendChild(b)})}
function startSave(i){const s=saves[i]||{level:0,parts:0,name:'Novo jogo'};activeSave=i;loadLevel(Math.min(s.level||0,levels.length-1));loading.classList.add('hidden');talk(dialogues[level]||[],()=>cutscene=false)}
let activeSave=0;
setTimeout(renderSaves,600);

